-- AP automation seed data (generated; do not edit). Load: sqlite3 ap.db < seed.sql
BEGIN;
-- Primary actors: requesters, approvers, AP analysts, process owners, system admins.
CREATE TABLE employee (
  employee_id TEXT PRIMARY KEY,
  full_name TEXT NOT NULL,
  department TEXT NOT NULL CHECK (department IN ('OPERATIONS', 'IT', 'FACILITIES', 'MANUFACTURING', 'MARKETING', 'FINANCE')),
  role TEXT NOT NULL CHECK (role IN ('REQUESTER', 'APPROVER_L1', 'APPROVER_L2', 'AP_ANALYST', 'PROCESS_OWNER', 'SYSTEM_ADMIN')),
  approval_limit NUMERIC(14,2),
  status TEXT NOT NULL CHECK (status IN ('ACTIVE'))
);

-- Supplier master. Created first; every PO and invoice references it.
CREATE TABLE vendor (
  vendor_id TEXT PRIMARY KEY,
  vendor_code TEXT NOT NULL UNIQUE,
  vendor_name TEXT NOT NULL UNIQUE,
  tax_id TEXT NOT NULL UNIQUE,
  country TEXT NOT NULL CHECK (country IN ('US', 'IN', 'GB', 'DE', 'SG')),
  primary_category TEXT NOT NULL CHECK (primary_category IN ('IT_HARDWARE', 'OFFICE_SUPPLIES', 'MRO', 'PACKAGING', 'RAW_MATERIALS', 'FACILITIES_SUPPLIES')),
  payment_terms TEXT NOT NULL CHECK (payment_terms IN ('NET15', 'NET30', 'NET45', 'NET60')),
  payment_method TEXT NOT NULL CHECK (payment_method IN ('ACH', 'WIRE')),
  currency TEXT NOT NULL CHECK (currency IN ('USD')),
  preferred_channel TEXT NOT NULL CHECK (preferred_channel IN ('EMAIL', 'PDF_UPLOAD', 'EDI')),
  status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'CLOSED')),
  effective_from DATE NOT NULL,
  effective_to DATE
);

-- Purchase order header.
CREATE TABLE purchase_order (
  po_id TEXT PRIMARY KEY,
  vendor_id TEXT NOT NULL,
  po_date DATE NOT NULL,
  requester_id TEXT NOT NULL,
  department TEXT NOT NULL CHECK (department IN ('OPERATIONS', 'IT', 'FACILITIES', 'MANUFACTURING', 'MARKETING', 'FINANCE')),
  currency TEXT NOT NULL CHECK (currency IN ('USD')),
  status TEXT NOT NULL CHECK (status IN ('OPEN', 'PARTIALLY_RECEIVED', 'FULLY_RECEIVED')),
  line_count INTEGER NOT NULL,
  subtotal NUMERIC(14,2) NOT NULL,
  tax_amount NUMERIC(14,2) NOT NULL,
  total_amount NUMERIC(14,2) NOT NULL,
  FOREIGN KEY (vendor_id) REFERENCES vendor(vendor_id),
  FOREIGN KEY (requester_id) REFERENCES employee(employee_id)
);

-- PO line: what was ordered, at what price and tax code.
CREATE TABLE purchase_order_line (
  po_line_id TEXT PRIMARY KEY,
  po_id TEXT NOT NULL,
  line_number INTEGER NOT NULL,
  sku TEXT NOT NULL,
  description TEXT NOT NULL,
  uom TEXT NOT NULL CHECK (uom IN ('EA', 'BOX', 'ROLL', 'KG', 'L', 'HR', 'MO', 'PAIR', 'SET')),
  quantity INTEGER NOT NULL,
  unit_price NUMERIC(14,2) NOT NULL,
  tax_code TEXT NOT NULL CHECK (tax_code IN ('TX00', 'TX05', 'TX12', 'TX18')),
  tax_rate NUMERIC(8,4) NOT NULL,
  line_amount NUMERIC(14,2) NOT NULL,
  tax_amount NUMERIC(14,2) NOT NULL,
  FOREIGN KEY (po_id) REFERENCES purchase_order(po_id)
);

-- Goods receipt note (GRN) header: one delivery against a PO.
CREATE TABLE goods_receipt (
  grn_id TEXT PRIMARY KEY,
  po_id TEXT NOT NULL,
  receipt_date DATE NOT NULL,
  warehouse TEXT NOT NULL CHECK (warehouse IN ('WH-NORTH', 'WH-SOUTH', 'WH-EAST', 'WH-WEST')),
  status TEXT NOT NULL CHECK (status IN ('POSTED')),
  FOREIGN KEY (po_id) REFERENCES purchase_order(po_id)
);

-- Quantity received per PO line in one delivery.
CREATE TABLE goods_receipt_line (
  grn_line_id TEXT PRIMARY KEY,
  grn_id TEXT NOT NULL,
  po_line_id TEXT NOT NULL,
  line_number INTEGER NOT NULL,
  quantity_received INTEGER NOT NULL,
  receipt_type TEXT NOT NULL CHECK (receipt_type IN ('FULL', 'PARTIAL', 'OVER')),
  FOREIGN KEY (grn_id) REFERENCES goods_receipt(grn_id),
  FOREIGN KEY (po_line_id) REFERENCES purchase_order_line(po_line_id)
);

-- Append-only state history for vendors and POs (never overwritten).
CREATE TABLE lifecycle_event (
  event_id TEXT PRIMARY KEY,
  entity_type TEXT NOT NULL CHECK (entity_type IN ('VENDOR', 'PURCHASE_ORDER')),
  entity_id TEXT NOT NULL,
  from_state TEXT CHECK (from_state IN ('ACTIVE', 'CLOSED', 'OPEN', 'PARTIALLY_RECEIVED', 'FULLY_RECEIVED')),
  to_state TEXT NOT NULL CHECK (to_state IN ('ACTIVE', 'CLOSED', 'OPEN', 'PARTIALLY_RECEIVED', 'FULLY_RECEIVED')),
  event_date DATE NOT NULL,
  detail TEXT
);

-- Invoice as issued by the vendor (truth). The pipeline never reads this table; it re-derives these fields from the raw document.
CREATE TABLE invoice (
  invoice_id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL UNIQUE,
  vendor_id TEXT NOT NULL,
  po_id TEXT,
  vendor_invoice_number TEXT NOT NULL,
  invoice_date DATE NOT NULL,
  received_at TIMESTAMP NOT NULL,
  channel TEXT NOT NULL CHECK (channel IN ('EMAIL', 'PDF_UPLOAD', 'EDI')),
  currency TEXT NOT NULL CHECK (currency IN ('USD')),
  payment_terms TEXT NOT NULL CHECK (payment_terms IN ('NET15', 'NET30', 'NET45', 'NET60')),
  due_date DATE NOT NULL,
  line_count INTEGER NOT NULL,
  subtotal NUMERIC(14,2) NOT NULL,
  tax_amount NUMERIC(14,2) NOT NULL,
  grand_total NUMERIC(14,2) NOT NULL,
  stated_total NUMERIC(14,2) NOT NULL,
  FOREIGN KEY (vendor_id) REFERENCES vendor(vendor_id),
  FOREIGN KEY (po_id) REFERENCES purchase_order(po_id)
);

-- Invoice line as issued by the vendor.
CREATE TABLE invoice_line (
  invoice_line_id TEXT PRIMARY KEY,
  invoice_id TEXT NOT NULL,
  line_number INTEGER NOT NULL,
  po_line_id TEXT,
  sku TEXT NOT NULL,
  description TEXT NOT NULL,
  uom TEXT NOT NULL CHECK (uom IN ('EA', 'BOX', 'ROLL', 'KG', 'L', 'HR', 'MO', 'PAIR', 'SET')),
  quantity INTEGER NOT NULL,
  unit_price NUMERIC(14,2) NOT NULL,
  tax_code TEXT NOT NULL CHECK (tax_code IN ('TX00', 'TX05', 'TX12', 'TX18')),
  tax_rate NUMERIC(8,4) NOT NULL,
  line_amount NUMERIC(14,2) NOT NULL,
  tax_amount NUMERIC(14,2) NOT NULL,
  FOREIGN KEY (invoice_id) REFERENCES invoice(invoice_id),
  FOREIGN KEY (po_line_id) REFERENCES purchase_order_line(po_line_id)
);

-- Header fields extracted from the raw document.
CREATE TABLE extracted_invoice (
  document_id TEXT PRIMARY KEY,
  layout TEXT NOT NULL CHECK (layout IN ('CLASSIC', 'EMAIL', 'EDI', 'LLM')),
  vendor_name TEXT,
  vendor_tax_id TEXT,
  vendor_invoice_number TEXT,
  invoice_date DATE,
  po_number TEXT,
  currency TEXT,
  payment_terms TEXT,
  subtotal NUMERIC(14,2),
  tax_amount NUMERIC(14,2),
  stated_total NUMERIC(14,2),
  line_count INTEGER NOT NULL,
  confidence NUMERIC(8,4) NOT NULL
);

-- Lines extracted from the raw document.
CREATE TABLE extracted_invoice_line (
  extracted_line_id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL,
  line_number INTEGER NOT NULL,
  sku TEXT NOT NULL,
  description TEXT NOT NULL,
  quantity INTEGER NOT NULL,
  unit_price NUMERIC(14,2) NOT NULL,
  tax_code TEXT NOT NULL,
  line_amount NUMERIC(14,2) NOT NULL,
  FOREIGN KEY (document_id) REFERENCES extracted_invoice(document_id)
);

-- One row per processed invoice: match result, exceptions, decision.
CREATE TABLE invoice_decision (
  invoice_id TEXT PRIMARY KEY,
  document_id TEXT NOT NULL UNIQUE,
  vendor_id TEXT,
  po_id TEXT,
  vendor_invoice_number TEXT,
  invoice_date DATE,
  computed_total NUMERIC(14,2) NOT NULL,
  match_status TEXT NOT NULL CHECK (match_status IN ('MATCHED', 'MATCHED_WITHIN_TOLERANCE', 'NON_PO', 'PRICE_VARIANCE', 'QTY_VARIANCE', 'TAX_VARIANCE', 'NO_RECEIPT', 'NOT_EVALUATED')),
  primary_exception TEXT CHECK (primary_exception IN ('EXTRACTION_INCOMPLETE', 'VENDOR_UNKNOWN', 'DUPLICATE_INVOICE', 'VENDOR_CLOSED', 'VENDOR_MISMATCH', 'PO_NOT_FOUND', 'TOTAL_MISMATCH', 'DATE_BEFORE_PO', 'MISSING_RECEIPT', 'TAX_MISMATCH', 'QTY_EXCEEDS_PO', 'QTY_EXCEEDS_RECEIPT', 'PRICE_VARIANCE')),
  exception_codes TEXT,
  exception_count INTEGER NOT NULL,
  final_status TEXT NOT NULL CHECK (final_status IN ('PAYMENT_READY', 'ON_HOLD')),
  payment_ready BOOLEAN NOT NULL,
  approval_path TEXT CHECK (approval_path IN ('AUTO', 'L1', 'L1>L2')),
  duplicate_of_invoice_id TEXT,
  route_queue TEXT CHECK (route_queue IN ('AP_OPERATIONS', 'VENDOR_MASTER', 'RECEIVING_CONFIRMATION', 'TAX_REVIEW', 'PROCUREMENT_REVIEW')),
  assigned_to TEXT,
  extraction_confidence NUMERIC(8,4) NOT NULL,
  processed_at TIMESTAMP NOT NULL,
  FOREIGN KEY (invoice_id) REFERENCES invoice(invoice_id),
  FOREIGN KEY (vendor_id) REFERENCES vendor(vendor_id),
  FOREIGN KEY (po_id) REFERENCES purchase_order(po_id),
  FOREIGN KEY (duplicate_of_invoice_id) REFERENCES invoice_decision(invoice_id),
  FOREIGN KEY (assigned_to) REFERENCES employee(employee_id)
);

-- Bridge (N:M) between invoice lines and goods receipt lines; quantity allocated FIFO.
CREATE TABLE invoice_match (
  match_id TEXT PRIMARY KEY,
  invoice_line_id TEXT NOT NULL,
  grn_line_id TEXT NOT NULL,
  matched_qty INTEGER NOT NULL,
  FOREIGN KEY (invoice_line_id) REFERENCES invoice_line(invoice_line_id),
  FOREIGN KEY (grn_line_id) REFERENCES goods_receipt_line(grn_line_id)
);

-- Every exception raised, routed to a queue and owner with an SLA.
CREATE TABLE invoice_exception (
  exception_id TEXT PRIMARY KEY,
  invoice_id TEXT NOT NULL,
  invoice_line_id TEXT,
  exception_code TEXT NOT NULL CHECK (exception_code IN ('EXTRACTION_INCOMPLETE', 'VENDOR_UNKNOWN', 'DUPLICATE_INVOICE', 'VENDOR_CLOSED', 'VENDOR_MISMATCH', 'PO_NOT_FOUND', 'TOTAL_MISMATCH', 'DATE_BEFORE_PO', 'MISSING_RECEIPT', 'TAX_MISMATCH', 'QTY_EXCEEDS_PO', 'QTY_EXCEEDS_RECEIPT', 'PRICE_VARIANCE')),
  severity TEXT NOT NULL CHECK (severity IN ('HIGH', 'MEDIUM')),
  is_primary BOOLEAN NOT NULL,
  queue TEXT NOT NULL CHECK (queue IN ('AP_OPERATIONS', 'VENDOR_MASTER', 'RECEIVING_CONFIRMATION', 'TAX_REVIEW', 'PROCUREMENT_REVIEW')),
  assigned_to TEXT NOT NULL,
  detail TEXT NOT NULL,
  expected_value TEXT,
  actual_value TEXT,
  status TEXT NOT NULL CHECK (status IN ('OPEN')),
  created_at TIMESTAMP NOT NULL,
  sla_due_at TIMESTAMP NOT NULL,
  FOREIGN KEY (invoice_id) REFERENCES invoice_decision(invoice_id),
  FOREIGN KEY (assigned_to) REFERENCES employee(employee_id)
);

-- Approval records, created only for eligible (exception-free) invoices.
CREATE TABLE approval (
  approval_id TEXT PRIMARY KEY,
  invoice_id TEXT NOT NULL,
  level INTEGER NOT NULL,
  approver_type TEXT NOT NULL CHECK (approver_type IN ('SYSTEM', 'HUMAN')),
  approver_id TEXT,
  decision TEXT NOT NULL CHECK (decision IN ('APPROVED')),
  policy_rule TEXT NOT NULL,
  decided_at TIMESTAMP NOT NULL,
  FOREIGN KEY (invoice_id) REFERENCES invoice_decision(invoice_id),
  FOREIGN KEY (approver_id) REFERENCES employee(employee_id)
);

-- Payment scheduled for approved invoices only (1:1 with invoice).
CREATE TABLE payment (
  payment_id TEXT PRIMARY KEY,
  invoice_id TEXT NOT NULL UNIQUE,
  vendor_id TEXT NOT NULL,
  amount NUMERIC(14,2) NOT NULL,
  currency TEXT NOT NULL CHECK (currency IN ('USD')),
  method TEXT NOT NULL CHECK (method IN ('ACH', 'WIRE')),
  scheduled_date DATE NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('SCHEDULED')),
  created_at TIMESTAMP NOT NULL,
  FOREIGN KEY (invoice_id) REFERENCES invoice_decision(invoice_id),
  FOREIGN KEY (vendor_id) REFERENCES vendor(vendor_id)
);

-- Append-only invoice state history.
CREATE TABLE invoice_event (
  event_id TEXT PRIMARY KEY,
  invoice_id TEXT NOT NULL,
  seq INTEGER NOT NULL,
  from_state TEXT CHECK (from_state IN ('RECEIVED', 'EXTRACTED', 'VALIDATED', 'MATCHED', 'PENDING_APPROVAL', 'APPROVED', 'PAYMENT_READY', 'ON_HOLD')),
  to_state TEXT NOT NULL CHECK (to_state IN ('RECEIVED', 'EXTRACTED', 'VALIDATED', 'MATCHED', 'PENDING_APPROVAL', 'APPROVED', 'PAYMENT_READY', 'ON_HOLD')),
  event_ts TIMESTAMP NOT NULL,
  actor TEXT NOT NULL,
  detail TEXT,
  FOREIGN KEY (invoice_id) REFERENCES invoice_decision(invoice_id)
);

COMMIT;
